(() => {
  const $ = (id) => document.getElementById(id);
  const title = $('title-screen'), game = $('game-screen'), modalBackdrop = $('modal-backdrop');
  const saveKey = 'first-light-save-v1';
  const initial = () => ({ node: 'morning', form: 48, bond: 50, well: 62, choices: [], journal: [], seen: [], sound: false });
  let state = initial(), locked = false;

  const scenes = {
    morning: { chapter:'THE DAY BEFORE', day:'01', weekday:'FRIDAY', time:'6:18 AM', location:"MARA'S ROOM", art:'bedroom', speaker:'MARA', text:'The alarm says 6:18. My legs say absolutely not. Somewhere between the two is the girl who still has to make the Northside roster.', thought:'One more day until tryouts.', options:[['Get up. Do ten minutes of touches before school.','practice','form',5,'I can be nervous after I get the ball moving.'],['Five more minutes. I need to be a person first.','breakfast','well',6,'Rest is training too. I am allowed to be a person.']] },
    breakfast: { chapter:'THE DAY BEFORE', day:'01', weekday:'FRIDAY', time:'7:02 AM', location:'THE KITCHEN', art:'kitchen', speaker:'MOM', text:'"Big day tomorrow," Mom says, setting down a plate like she can feed the worry right out of me. "Do you want to talk about it?"', options:[['Tell her I am scared I will let everyone down.','bus','bond',7,'Saying it out loud makes the fear feel a little less like a secret.'],['Ask if she can watch from the stands.','bus','bond',4,'She smiles. "Wouldn’t miss it for anything."']] },
    practice: { chapter:'THE DAY BEFORE', day:'01', weekday:'FRIDAY', time:'6:34 AM', location:'THE BACK GARDEN', art:'garden', speaker:'MARA', text:'The garden is barely long enough for a pass. I set two flowerpots up as defenders and work the ball through the gap until my breath comes easy.', options:[['Keep going until my calves complain.','bus','form',7,'My left foot is waking up. My calves have filed a complaint.'],['Stop while it still feels good. Save something for tomorrow.','bus','well',5,'Leave a little in the tank. The field will still be there tomorrow.']] },
    bus: { chapter:'SMALL HOURS', day:'01', weekday:'FRIDAY', time:'7:46 AM', location:'THE BUS STOP', art:'bus', speaker:'JULES', text:'Jules is sitting on the curb, sketchbook open on one knee. They draw a tiny crown on the stick figure in their margin. "For your future team photo."', options:[['Make them laugh: "Draw me taller, at least."','school','bond',5,'Jules grins. "I only draw what I see."'],['Ask if they will come to the tryout.','school','bond',8,'"Front row," Jules says. "I will bring the embarrassing sign."']] },
    school: { chapter:'SMALL HOURS', day:'01', weekday:'FRIDAY', time:'10:21 AM', location:'SCHOOL HALLWAY', art:'hallway', speaker:'TESS', text:'Tess catches up between classes. She has been on Northside’s roster for two years. "Coach is looking for someone who sees the whole field," she says. "Not just the goal."', options:[['Ask what she means. Really listen.','lunch',null,0,'"Make the pass that nobody else sees. That is how you make a team."'],['Tell her I already know how to play.','lunch','form',2,'Tess nods, not quite convinced. The bell saves me from having to fill the silence.']] },
    lunch: { chapter:'SMALL HOURS', day:'01', weekday:'FRIDAY', time:'12:14 PM', location:'THE COURTYARD', art:'courtyard', speaker:'JULES', text:'Jules has claimed our usual sunny bench. They nudge half their tangerine toward me. "You have been living on nerves and granola bars."', options:[['Put my phone away and stay a while.','after-school','bond',7,'For fifteen minutes, tomorrow can wait. Jules tells me about their new comic.'],['Eat fast—there is still time to get a few touches in.','after-school','form',4,'I get a little practice in before the next bell. A little less time with Jules.']] },
    'after-school': { chapter:'THE EVENING BEFORE', day:'01', weekday:'FRIDAY', time:'4:12 PM', location:'NORTHSIDE COMMUNITY FIELD', art:'field', speaker:'TESS', text:'The field is quiet except for the net tapping in the breeze. Tess tosses me a ball. "One last run? Or do you want to talk through the drills?"', options:[['Run the cone course. Then one more time.','walk-home','form',7,'One touch, two, cut. The ball listens when I stop trying to force it.'],['Walk the field together. Ask how she handled her first tryout.','walk-home','bond',7,'She admits she nearly quit before the first whistle. "You do not have to be fearless."']] },
    'walk-home': { chapter:'THE EVENING BEFORE', day:'01', weekday:'FRIDAY', time:'6:03 PM', location:'THE WALK HOME', art:'sunset', speaker:'MARA', text:'The evening light pools gold along the sidewalk. My bag is heavy with boots. Tomorrow feels close enough to touch, and somehow farther away than ever.', thought:'Whatever happens, I showed up.', options:[['Call Mom and ask what is for dinner.','dinner',null,0,'The ordinary details feel like something solid to hold.'],['Text Jules: “You are actually coming tomorrow, right?”','dinner','bond',4,'Three dots. Then: “Already made the sign. No take-backs.”']] },
    dinner: { chapter:'THE EVENING BEFORE', day:'01', weekday:'FRIDAY', time:'7:11 PM', location:'HOME', art:'dinner', speaker:'MOM', text:'Dinner is warm and familiar. Mom asks me what I want from tomorrow—not the result. The thing I want, underneath all the noise.', options:[['To play like myself. Whatever that looks like.','night',null,0,'Mom lifts her glass. "That sounds like a good thing to want."'],['To prove I belong there.','night','form',2,'"You belong on the field before anyone writes your name on a list," she says.']] },
    night: { chapter:'THE EVENING BEFORE', day:'01', weekday:'FRIDAY', time:'10:38 PM', location:"MARA'S ROOM", art:'bedroom-night', speaker:'MARA', text:'Boots by the door. Kit folded. Phone on silent—except for one last message from Jules: a doodle of me, tiny and determined, under a huge hand-lettered YOU GOT THIS.', thought:'Tomorrow, I will be there.', options:[['Put the phone down. Sleep is part of the plan.','tryout-arrival','well',5,'I take a slow breath. The dark is gentle for once.'],['Watch one more clip of Tess’s footwork.','tryout-arrival','form',3,'One move. Not five. I put the phone away before it becomes morning.']] },
    'tryout-arrival': { chapter:'THE TRYOUT', day:'02', weekday:'SATURDAY', time:'8:42 AM', location:'NORTHSIDE TRAINING GROUND', art:'field-morning', speaker:'MARA', text:'The Northside crest is stitched into every pinnie. Around me, girls stretch, juggle, size one another up. My stomach tries to climb into my throat.', thought:'This is what I came for.', options:[['Find Tess. Ask her to warm up together.','tryout-warmup','bond',5,'It helps to see one familiar face. Then I start to see all the others as people, not competition.'],['Start juggling. Make the ball the only thing in the world.','tryout-warmup','form',5,'One, two, three, four. My breath finds the rhythm.']] },
    'tryout-warmup': { chapter:'THE TRYOUT', day:'02', weekday:'SATURDAY', time:'9:05 AM', location:'THE WARM-UP GRID', art:'field-morning', speaker:'COACH REYES', text:'Coach Reyes blows the whistle. "I do not need perfect. I need curious. Find the pass that makes your teammate better." The first drill begins.', options:[['Play the safe pass and move into space.','tryout-drill','form',4,'Keep it simple. Keep moving. The game starts to open up.'],['Try the threaded pass between two defenders.','tryout-drill','form',6,'It slips through! A teammate gets there just in time. Risk is not the same as showing off.']] },
    'tryout-drill': { chapter:'THE TRYOUT', day:'02', weekday:'SATURDAY', time:'9:36 AM', location:'THE SMALL-SIDED GAME', art:'match', speaker:'MARA', text:'A loose ball skips toward the sideline. Tess is open on my left, but a defender is already closing. For a split second, there is only the field and the choice.', options:[['Pass to Tess. Trust the space she sees.','tryout-whistle','bond',5,'The ball finds Tess, Tess finds the run, and the play becomes ours.'],['Take the defender on. Go for the shot.','tryout-whistle','form',6,'I cut inside. The shot is wide—but I made them work for it.']] },
    'tryout-whistle': { chapter:'THE TRYOUT', day:'02', weekday:'SATURDAY', time:'10:14 AM', location:'THE TOUCHLINE', art:'match', speaker:'COACH REYES', text:'The whistle cuts through the morning. Everyone gathers at the sideline, trying not to look like they are trying not to look. Coach reads from her clipboard.', options:[['Hold my breath. Wait for my name.','aftermath',null,0,'For a second, even the birds seem to stop singing.'],['Look at the other players. We did this together.','aftermath','bond',3,'Somebody squeezes my shoulder. It is Tess. I remember to breathe.']] },
    aftermath: { chapter:'AFTER THE WHISTLE', day:'02', weekday:'SATURDAY', time:'10:19 AM', location:'THE TOUCHLINE', art:'field-morning', speaker:'COACH REYES', text:'"Mara Vale." Coach taps her clipboard. "I want you at the second evaluation next week. This is not a promise. It is a door. Show me what you do with it."', thought:'Not the answer. A beginning.', options:[['Thank her. Ask what I should work on.','news', 'form',2,'Coach gives me a drill list. There is a next step, and I know how to take those.'],['Find Mom and Jules in the stands first.','news','bond',5,'Mom has happy tears. Jules holds up a sign that says NICE PASS, NERD.']] },
    news: { chapter:'A LITTLE LATER', day:'02', weekday:'SATURDAY', time:'12:06 PM', location:'THE BLEACHERS', art:'bleachers', speaker:'TESS', text:'Tess sits beside me, shoes dangling over the bleacher edge. "Second evaluation," she says. "That is how it started for me, too." She bumps my shoulder.', options:[['Ask if she wants to train together next week.','home','bond',6,'"Yeah," she says. "We can both get better."'],['Tell her I want to earn it on my own.','home','form',3,'She nods. "Fair. Just do not disappear into your own head, okay?"']] },
    home: { chapter:'A LITTLE LATER', day:'02', weekday:'SATURDAY', time:'1:33 PM', location:'THE WALK HOME', art:'sunset', speaker:'JULES', text:'Jules falls into step with me, the sign tucked under one arm. "So," they ask, "what do you want to do now? Like, right now—not next week."', options:[['Get something to eat. Let this day be good.','ending', 'well',5,'The whole afternoon is still ahead of us. That feels like enough.'],['Go kick the ball around while the field is empty.','ending','form',4,'The field is quiet. For once, I am not trying to prove anything.']] },
    ending: { chapter:'FIRST LIGHT', day:'02', weekday:'SATURDAY', time:'2:10 PM', location:'NORTHSIDE FIELD', art:'gold-field', speaker:'MARA', text:'The second evaluation is next week. The team is not mine yet. But neither is the future, and for the first time, that feels less like a threat than an invitation.', ending:true }
  };

  function load() { try { const data = JSON.parse(localStorage.getItem(saveKey)); if (data && data.node && scenes[data.node]) state = {...initial(), ...data}; } catch {} }
  function save() { try { localStorage.setItem(saveKey, JSON.stringify(state)); } catch {} }
  function clamp(n) { return Math.max(0, Math.min(100,n)); }
  function setStat(stat, amount) { if (stat && amount) state[stat] = clamp(state[stat] + amount); }
  function artUrl(name) {
    const pics = {
      bedroom:'photo-1519238263530-99bdd11df2ea', kitchen:'photo-1495546968767-f0573cca821e', garden:'photo-1594736797933-d0401ba2fe65',
      bus:'photo-1507035895480-2b3156c31fc8', hallway:'photo-1503676260728-1c00da094a0b', courtyard:'photo-1529390079861-591de354faf5',
      field:'photo-1522778119026-d647f0596c20', sunset:'photo-1470770841072-f978cf4d019e', dinner:'photo-1517248135467-4c7edcad34c4',
      'bedroom-night':'photo-1519682337058-a94d519337bc','field-morning':'photo-1526232761682-d26e03ac148e',match:'photo-1517466787929-bc90951d0974',
      bleachers:'photo-1486286701208-1d58e9338013','gold-field':'photo-1522778119026-d647f0596c20'
    };
    const id = pics[name] || pics.field;
    const colors = {bedroom:'#c69b81',kitchen:'#d2ad8d',garden:'#94a17b',bus:'#829aa0',hallway:'#a69d93',courtyard:'#9da879',field:'#7e9b72',sunset:'#d38f73',dinner:'#aa8068','bedroom-night':'#514c62','field-morning':'#8ca49a',match:'#829a79',bleachers:'#be9276','gold-field':'#c99862'};
    return `linear-gradient(180deg,${colors[name]||'#78916f'}33,${colors[name]||'#78916f'}55),url(https://images.unsplash.com/${id}?auto=format&fit=crop&w=1800&q=85)`;
  }
  function updateStats() { $('form-bar').style.width=state.form+'%'; $('bond-bar').style.width=state.bond+'%'; $('well-bar').style.width=state.well+'%'; }
  function updateContinue() { $('continue-button').hidden = !localStorage.getItem(saveKey); }
  function render() {
    const s = scenes[state.node]; if (!s) return;
    locked = false; $('chapter-name').textContent=s.chapter; $('day-number').textContent=s.day; $('day-name').textContent=s.weekday; $('scene-time').textContent=s.time; $('scene-location').textContent=s.location;
    $('scene-art').style.backgroundImage=artUrl(s.art); $('speaker-name').textContent=s.speaker; $('speaker-avatar').textContent=s.speaker==='MARA'?'M':s.speaker==='COACH REYES'?'C':s.speaker[0]; $('dialogue-text').textContent=s.text;
    $('thought-bubble').hidden=!s.thought; $('thought-bubble').textContent=s.thought||''; $('dialogue-index').textContent=`${String(Math.max(1,state.seen.length)).padStart(2,'0')} / 18`;
    const list=$('choice-list'); list.innerHTML=''; $('next-button').hidden=!!s.options || !!s.ending;
    if(s.options) s.options.forEach(([label,next,stat,amount,note])=>{const b=document.createElement('button');b.className='choice-button';b.textContent=label;b.onclick=()=>choose(next,stat,amount,note);list.appendChild(b)});
    if(s.ending){$('next-button').hidden=false;$('next-button').innerHTML='SEE YOUR STORY <span>→</span>';$('next-button').onclick=showEnding;}
    else {$('next-button').innerHTML='CONTINUE <span>→</span>';$('next-button').onclick=advance;}
    $('dialogue-hint').textContent=s.options?'CHOOSE WHAT YOU DO':'CLICK ANYWHERE OR PRESS SPACE';
    updateStats(); state.seen.push(state.node); state.seen=[...new Set(state.seen)]; save(); $('autosave-label').textContent='PROGRESS SAVES AUTOMATICALLY';
  }
  function choose(next, stat, amount, note) { if(locked)return; locked=true; setStat(stat,amount); if(note) state.journal.push({day:scenes[state.node].day,text:note}); state.choices.push({node:state.node,next}); state.node=next; save(); render(); }
  function advance() { if(locked)return; locked=true; if(state.node==='tryout-arrival') state.node='tryout-warmup'; else if(state.node==='tryout-warmup') state.node='tryout-drill'; else if(state.node==='tryout-drill') state.node='tryout-whistle'; else if(state.node==='tryout-whistle') state.node='aftermath'; else if(state.node==='aftermath') state.node='news'; else if(state.node==='news') state.node='home'; else if(state.node==='home') state.node='ending'; else state.node='ending'; save(); render(); }
  function showEnding() {
    const f=state.form,b=state.bond,w=state.well;
    let titleText, copy;
    if(f>=70){titleText='A place to begin';copy='Your work speaks for itself. Coach wants to see you at the second evaluation, and you meet the news with clear eyes. You have the form to compete, and the patience to keep growing.'}
    else if(b>=68){titleText='Not alone on the field';copy='The roster is still undecided, but the people beside you are certain. Tess offers to train together. Jules already has a new sign in mind. You do not have to figure out the next step alone.'}
    else if(w<40){titleText='A slower kind of brave';copy='You are tired, and you finally let yourself say it. The next evaluation can wait until you have slept, eaten, and found your feet again. Taking care of yourself is part of staying in the game.'}
    else{titleText='The door stays open';copy='The roster is not yours yet. But Coach saw something worth another look—and you did, too. There is more than one way to belong on a field. Your next chapter is yours to write.'}
    $('modal-eyebrow').textContent='YOUR STORY SO FAR';$('modal-title').textContent=titleText;
    $('modal-content').innerHTML=`<p class="ending-copy">${copy}</p><div class="ending-score"><div><b>${f}</b><span>FORM</span></div><div><b>${b}</b><span>CONNECTION</span></div><div><b>${w}</b><span>WELLBEING</span></div></div><div class="modal-actions"><button id="replay-button">↻ PLAY AGAIN</button><button id="journal-from-end">☷ STORY JOURNAL</button></div>`;
    modalBackdrop.hidden=false; $('modal-close').onclick=()=>modalBackdrop.hidden=true; $('replay-button').onclick=()=>{state=initial();save();modalBackdrop.hidden=true;render()}; $('journal-from-end').onclick=()=>showJournal(true);
  }
  function showJournal(fromEnd=false) {
    $('modal-eyebrow').textContent='FIELD NOTES';$('modal-title').textContent='Your journal';
    const entries=state.journal.slice(-8).reverse();
    $('modal-content').innerHTML=entries.length?entries.map(e=>`<div class="journal-entry"><b>DAY ${e.day} · A MOMENT YOU KEPT</b>${escapeHtml(e.text)}</div>`).join(''):'<p class="ending-copy">The journal is still blank. The little things you choose to remember will find their way here.</p>';
    if(fromEnd){const b=document.createElement('button');b.className='modal-close';b.textContent='×';b.onclick=()=>modalBackdrop.hidden=true;}
    modalBackdrop.hidden=false;
  }
  function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function start(resume=false){if(!resume)state=initial(); if(!scenes[state.node])state.node='morning';title.hidden=true;game.hidden=false;render();}
  $('play-button').onclick=()=>start(false); $('continue-button').onclick=()=>{load();start(true)}; $('home-button').onclick=()=>{game.hidden=true;title.hidden=false;updateContinue()}; $('journal-button').onclick=()=>showJournal(); $('modal-close').onclick=()=>modalBackdrop.hidden=true;
  $('sound-button').onclick=()=>{state.sound=!state.sound;$('sound-label').textContent=state.sound?'SOUND ON':'SOUND OFF';save();};
  $('fast-forward').onclick=()=>{if(state.node==='ending')return; const next=state.node==='morning'?'bus':state.node==='bus'?'school':state.node==='school'?'lunch':state.node==='lunch'?'after-school':state.node==='after-school'?'walk-home':state.node==='walk-home'?'dinner':state.node==='dinner'?'night':state.node==='night'?'tryout-arrival':state.node==='tryout-arrival'?'tryout-warmup':state.node==='tryout-warmup'?'tryout-drill':state.node==='tryout-drill'?'tryout-whistle':state.node==='tryout-whistle'?'aftermath':state.node==='aftermath'?'news':state.node==='news'?'home':'ending';state.node=next;render();};
  $('scene-art').addEventListener('click',()=>{if(scenes[state.node].options||scenes[state.node].ending)return;advance()});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!modalBackdrop.hidden)modalBackdrop.hidden=true;else{game.hidden=true;title.hidden=false;updateContinue()}} if(e.key==='Enter'||e.key===' '){if(!title.hidden&&e.key==='Enter')start(false);else if(!game.hidden&&!modalBackdrop.hidden===false)advance();}});
  load(); updateContinue();
})();

